// Extract the label the local model returned, default to Normal.
const out = $json.choices ? $json.choices[0].message.content.trim() : 'Normal';
const label = ['Urgent-Security','Urgent-Admin','Normal','FYI'].find(l => out.includes(l)) || 'Normal';
return [{ json: { label } }];

// Act on the label. Wire the real actions here:
//  - Gmail 'Add Label' node for Urgent-Security / FYI, or
//  - Todoist 'Create Task' (Q1 tag) for Urgent items, or
//  - Microsoft Outlook 'Move/Categorise' node.
return [{ json: { label: $json.label, action: 'wire your Gmail/Todoist/Outlook node here' } }];
